param([string]$CasePath)
$ErrorActionPreference='Stop';$c=Get-Content -LiteralPath $CasePath -Raw|ConvertFrom-Json
$pipe=$null;$audit=@{constructed=$false;connected=$false;message_mode=$false;ready_sent=$false;done_sent=$false;complete_received=$false;received=@();error=$null}
function WaitIO($t){if(-not $t.Wait(20000)){throw 'Server watchdog'};$t.GetAwaiter().GetResult()}
function Send($o){$b=[Text.Encoding]::UTF8.GetBytes(($o|ConvertTo-Json -Compress -Depth 8));$null=WaitIO($pipe.WriteAsync($b,0,$b.Length));$null=WaitIO($pipe.FlushAsync())}
function Recv{$m=[IO.MemoryStream]::new();$b=[byte[]]::new(211);try{do{$n=WaitIO($pipe.ReadAsync($b,0,$b.Length));if($n-eq 0){throw 'closed'};$m.Write($b,0,$n)}while(-not $pipe.IsMessageComplete);[Text.UTF8Encoding]::new($false,$true).GetString($m.ToArray())|ConvertFrom-Json}finally{$m.Dispose()}}
try{$pipe=[IO.Pipes.NamedPipeServerStream]::new($c.pipe,[IO.Pipes.PipeDirection]::InOut,1,[IO.Pipes.PipeTransmissionMode]::Message,[IO.Pipes.PipeOptions]::Asynchronous);$audit.constructed=$true;$audit.message_mode=$pipe.TransmissionMode-eq [IO.Pipes.PipeTransmissionMode]::Message;[IO.File]::WriteAllText($c.ready,'constructed');$null=WaitIO($pipe.WaitForConnectionAsync());$audit.connected=$true;if($c.mode-eq 'stall_ready'){$null=Recv;throw 'unexpected'};Send @{kind='ready'};$audit.ready_sent=$true;$got=[Collections.Generic.List[string]]::new();for($i=0;$i-lt $c.messages.Count;$i++){$x=Recv;if($x.kind-cne 'data'-or$x.seq-ne$i-or$x.payload-cne$c.messages[$i]){throw 'mismatch'};$got.Add([string]$x.payload);$audit.received=$got.ToArray();if($c.mode-eq 'stall_ack'-and$i-eq1){$null=Recv;throw 'unexpected'};Send @{kind='ack';seq=$i;payload=[string]$x.payload};if($c.mode-eq 'disconnect'-and$i-eq0){$pipe.Dispose();$pipe=$null;break}};if($c.mode-ne'disconnect'){$x=Recv;if($x.kind-cne'complete'-or$x.count-ne$c.messages.Count){throw 'complete mismatch'};$audit.complete_received=$true;if($c.mode-eq 'stall_done'){$null=Recv;throw 'unexpected'};Send @{kind='done';count=$c.messages.Count};$audit.done_sent=$true}}catch{$audit.error=$_.Exception.Message}finally{if($null-ne$pipe){$pipe.Dispose()};$audit|ConvertTo-Json -Depth 8|Set-Content -LiteralPath $c.server_result -Encoding utf8}
